import{_ as n,c as i,o as t,ah as a}from"./chunks/framework.oAolcYhj.js";const r="/Qonnectra-docs/pr-14/images/manual/teil-a/login_start.jpg",s="/Qonnectra-docs/pr-14/images/manual/teil-a/login_start_detail.jpg",l="/Qonnectra-docs/pr-14/images/manual/teil-a/login_navigation.jpg",d="/Qonnectra-docs/pr-14/images/manual/teil-a/login_sidebar.jpg",u="/Qonnectra-docs/pr-14/images/manual/teil-a/login_header.jpg",o="/Qonnectra-docs/pr-14/images/manual/teil-a/login_settings.jpg",z=JSON.parse('{"title":"3. Einstieg und Anmeldung","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/03-einstieg-und-anmeldung.md","filePath":"manual/teil-a-anwenderhandbuch/03-einstieg-und-anmeldung.md"}'),h={name:"manual/teil-a-anwenderhandbuch/03-einstieg-und-anmeldung.md"};function g(m,e,c,b,p,f){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="_3-einstieg-und-anmeldung" tabindex="-1">3. Einstieg und Anmeldung <a class="header-anchor" href="#_3-einstieg-und-anmeldung" aria-label="Permalink to &quot;3. Einstieg und Anmeldung&quot;">​</a></h1><h2 id="_3-1-zugang-zur-anwendung" tabindex="-1">3.1 Zugang zur Anwendung <a class="header-anchor" href="#_3-1-zugang-zur-anwendung" aria-label="Permalink to &quot;3.1 Zugang zur Anwendung&quot;">​</a></h2><p>Qonnectra wird über einen Webbrowser bedient; eine Installation auf Ihrem Rechner ist nicht nötig. Die Adresse zur Anmeldung erhalten Sie von Ihrer Organisation oder zuständigen Verwaltung. Auf der Anmeldeseite geben Sie unter der Überschrift „Anmelden“ Ihre Zugangsdaten ein:</p><ul><li>„Benutzername“</li><li>„Passwort“</li></ul><p>Beide Felder sind Pflichtfelder. Über das Augensymbol am rechten Rand des Passwortfelds können Sie Ihre Eingabe kurz sichtbar machen, um Tippfehler zu finden. Mit einem Klick auf „Login“ – oder mit der Eingabetaste – melden Sie sich an und gelangen zum Dashboard.</p><p class="img-row"><img src="'+r+'" alt="Screenshot Anmeldeseite mit dem Anmeldeformular auf der rechten Seite" data-zoomable="true"><img src="'+s+'" alt="Screenshot Ausschnittvergrößerung des Anmeldeformulars mit den Feldern „Benutzername“ und „Passwort“ und der Schaltfläche „Login“" data-zoomable="true"></p><p>Hinweis: Wenn Benutzername oder Passwort nicht stimmen, erscheint am unteren Bildschirmrand kurz die Meldung „Fehler beim Anmelden“ und Sie bleiben auf der Anmeldeseite. Prüfen Sie in diesem Fall die Groß- und Kleinschreibung sowie die Tastaturbelegung.</p><h3 id="_3-1-1-noch-keine-zugangsdaten" tabindex="-1">3.1.1 Noch keine Zugangsdaten? <a class="header-anchor" href="#_3-1-1-noch-keine-zugangsdaten" aria-label="Permalink to &quot;3.1.1 Noch keine Zugangsdaten?&quot;">​</a></h3><p>Falls Sie noch keine Zugangsdaten erhalten haben, wenden Sie sich bitte an Ihre Projektleitung oder Ihre Administration. Ein Benutzerkonto kann dort für Sie angelegt werden.</p><h3 id="_3-1-2-passwort-vergessen" tabindex="-1">3.1.2 Passwort vergessen? <a class="header-anchor" href="#_3-1-2-passwort-vergessen" aria-label="Permalink to &quot;3.1.2 Passwort vergessen?&quot;">​</a></h3><p>Derzeit gibt es keine „Passwort vergessen“-Funktion im System. Wenn Sie Ihr Passwort nicht mehr wissen, hilft Ihnen Ihre Projektleitung oder Administration weiter. Dort kann das Passwort zurückgesetzt oder ein neues vergeben werden.</p><h2 id="_3-2-navigation-in-der-anwendung" tabindex="-1">3.2 Navigation in der Anwendung <a class="header-anchor" href="#_3-2-navigation-in-der-anwendung" aria-label="Permalink to &quot;3.2 Navigation in der Anwendung&quot;">​</a></h2><p>Nach der Anmeldung befinden Sie sich auf dem Dashboard. Die Bedienoberfläche ist immer gleich aufgebaut und besteht aus drei Bereichen: der <strong>Navigationsleiste</strong> am linken Rand, der <strong>Kopfzeile</strong> am oberen Rand und der <strong>Inhaltsfläche</strong> in der Mitte. Dieser Abschnitt erläutert die Oberfläche und hilft beim schnellen Einstieg.</p><p><img src="'+l+'" alt="Screenshot Startbildschirm mit Hervorhebung der einzelnen Bestandteile der App" class="big no-border" data-zoomable="true"></p><h3 id="_3-2-1-navigationsleiste" tabindex="-1">3.2.1 Navigationsleiste <a class="header-anchor" href="#_3-2-1-navigationsleiste" aria-label="Permalink to &quot;3.2.1 Navigationsleiste&quot;">​</a></h3><p>Auf der linken Seite befindet sich die Navigationsleiste, mit der Sie zu allen verfügbaren Ansichten wechseln können. Die Einträge sind nach Themen gruppiert:</p><ul><li>„Info“ – „Dashboard“ (Startansicht mit Gesamtüberblick, siehe Kapitel <a href="./04-dashboard.html">Dashboard</a>) und „Karte“ (Netzinfrastruktur auf der Karte, siehe Kapitel <a href="./05-karte.html">Karte</a>)</li><li>„Funktionen“ – „Störungsanalyse“, „Nachverdichtung“, „Leitungsauskunft“ und „Wertermittlung“: Auswertungen und Verfahren, die auf den dokumentierten Daten aufbauen</li><li>„Rohr“ – „Verwaltung“ (Anlegen und Verwalten von Rohren und ihren Attributen, siehe Kapitel <a href="./06-rohrverwaltung.html">Rohrverwaltung</a>), „Zuordnung“ (Zuordnung der angelegten Rohre zu den Trassen, siehe Kapitel <a href="./07-rohrzuordnung.html">Rohrzuordnung</a>), „Verzweigung“ und „Mikrorohre“</li><li>„Kabel“ – „Netzschema“ und „Faserweg“</li><li>„Gebäude“ – „Adressen“</li></ul><p>Unterhalb dieser Gruppen steht die Gruppe „System“ mit „Logs“ und „Einstellungen“ (siehe Abschnitt 3.2.4).</p><p>Die Navigationsleiste bleibt beim Arbeiten in der Anwendung immer sichtbar, womit Sie schnellen Zugriff auf alle Funktionen haben. Der aktive Eintrag ist farbig hervorgehoben.</p><p><img src="'+d+'" alt="Screenshot Dashboard mit Hervorhebung der Navigationsleiste am linken Rand" data-zoomable="true"></p><p>Hinweis: Ist das Browserfenster niedrig, sind nicht alle Einträge gleichzeitig zu sehen. Scrollen Sie dann in der Navigationsleiste nach unten oder klappen Sie Gruppen zu, die Sie gerade nicht brauchen.</p><p>Ein Klick auf einen Gruppennamen – etwa „Funktionen“ – klappt die Gruppe zu und wieder auf. Einträge, die Sie nicht benötigen, können Sie dauerhaft ausblenden:</p><ol><li>Klicken Sie oben auf das Symbol mit den Schiebereglern rechts neben dem Schriftzug „Qonnectra“ („Seitenleiste anpassen“).</li><li>Klicken Sie neben einem Eintrag auf das Augensymbol („Ausblenden“). Ausgeblendete Einträge bleiben in diesem Modus blass sichtbar und lassen sich über „Einblenden“ zurückholen.</li><li>Klicken Sie erneut auf das Symbol mit den Schiebereglern („Fertig“), um die Anpassung zu beenden.</li></ol><p>Solange die Anpassung aktiv ist, steht daneben zusätzlich „Seitenleiste zurücksetzen“ zur Verfügung; damit werden alle ausgeblendeten Einträge und zugeklappten Gruppen wiederhergestellt.</p><p>Hinweis: Zugeklappte Gruppen und ausgeblendete Einträge merkt sich der Browser, in dem Sie sie eingestellt haben – auch über das Abmelden hinaus. An einem anderen Rechner oder in einem anderen Browser sehen Sie wieder die vollständige Navigationsleiste.</p><p>Hinweis: Welche Einträge Sie sehen, hängt von Ihren Rechten ab. Fehlt ein hier genannter Eintrag, ist er für Ihr Benutzerkonto nicht freigegeben – wenden Sie sich an Ihre Administration.</p><h3 id="_3-2-2-kopfzeile" tabindex="-1">3.2.2 Kopfzeile <a class="header-anchor" href="#_3-2-2-kopfzeile" aria-label="Permalink to &quot;3.2.2 Kopfzeile&quot;">​</a></h3><p>Oben links in der Anwendung befindet sich das Projektauswahl-Menü. Hier wählen Sie das Projekt aus, mit dem Sie aktuell arbeiten möchten. Bei einem Wechsel des Projekts aktualisieren sich automatisch alle angezeigten Inhalte. In den Kartenansichten steht daneben zusätzlich die Schaltfläche „Alle Projekte anzeigen“, mit der Sie die Beschränkung auf das gewählte Projekt vorübergehend aufheben.</p><p>Oben rechts in der Kopfzeile befinden sich folgende Optionen:</p><ul><li>Aktuelle Softwareversion, z. B. „v1.7.0“: Geben Sie diese Angabe mit an, wenn Sie einen Fehler bei Ihrem Systemadministrator melden.</li><li>Spracheinstellung: Deutsch („DE“) oder Englisch („EN“)</li><li>Verweis auf das Projekt bei GitHub, in dem Qonnectra entwickelt wird</li><li>Hell-/Dunkelmodus („Hell-/Dunkelmodus umschalten“): Im Hellmodus wird das Symbol für den Dunkelmodus (Mond) angezeigt und umgekehrt.</li><li>Abmelden: Um sich sicher abzumelden, klicken Sie auf das Tür-mit-Pfeil-Symbol. Danach werden Sie automatisch zur Anmeldeseite zurückgeleitet.</li></ul><p><img src="'+u+'" alt="Screenshot Dashboard mit Hervorhebung der Kopfzeile am oberen Rand" data-zoomable="true"></p><p>Hinweis: Wenn Ihre Installation eine Adresse für dieses Handbuch hinterlegt hat, erscheint zusätzlich ein Buchsymbol („Dokumentation“), das das Handbuch in einem neuen Tab öffnet. Andernfalls fehlt das Symbol.</p><h3 id="_3-2-3-inhalt" tabindex="-1">3.2.3 Inhalt <a class="header-anchor" href="#_3-2-3-inhalt" aria-label="Permalink to &quot;3.2.3 Inhalt&quot;">​</a></h3><p>In der zentralen Inhaltsfläche werden alle projektbezogenen Informationen angezeigt: Statistiken, Listen, Karten usw. Welche Inhalte sichtbar sind, hängt vom gewählten Projekt (oben links in der Kopfzeile), dem gewählten Navigationseintrag (linke Navigationsleiste) und ggf. von dem gewählten Reiter (meist unterhalb der Kopfzeile) ab.</p><p>Karten, Grafiken und Listen sind meist interaktiv: Beispielsweise können Sie in einem Diagramm mit der Maus über einen Datenpunkt fahren („hovern“), um Details anzuzeigen.</p><h3 id="_3-2-4-einstellungen" tabindex="-1">3.2.4 Einstellungen <a class="header-anchor" href="#_3-2-4-einstellungen" aria-label="Permalink to &quot;3.2.4 Einstellungen&quot;">​</a></h3><p>Ganz unten links, in der Gruppe „System“, finden Sie den Eintrag „Einstellungen“. Hier können individuelle Einstellungen vorgenommen werden, z. B. zu Ihrem Benutzerkonto, zur Darstellung der Karte oder zur Breite der Navigationsleiste („Erweitert“ mit Beschriftungen oder „Eingeklappt“ nur mit Symbolen). Darüber steht der Eintrag „Logs“ mit den Systemprotokollen; er ist nur mit den entsprechenden Rechten sichtbar.</p><p><img src="'+o+'" alt="Screenshot Dashboard mit Hervorhebung der Gruppe „System“ mit „Logs“ und „Einstellungen“ unten links" data-zoomable="true"></p><p>Hinweis: Wenn die Gruppe „System“ nicht zu sehen ist, scrollen Sie in der Navigationsleiste nach unten.</p>',39)])])}const w=n(h,[["render",g]]);export{z as __pageData,w as default};
